//    For each field in SIGNSCOPE constant:
//      <lowercase-key>:<type>:<value>\r\n
//    Then appended:
//      signscope:s:<SIGNSCOPE>\r\n
//      \0 (null terminator)
//    Encoded as UTF-16LE (no BOM).
