        private static int RunListUsers(string outPath)
        {
            if (string.IsNullOrEmpty(outPath))
            {
                Console.Error.WriteLine(PROGRAM_NAME + ": ERROR: --list-users requires an output file path");
                return 99;
            }

            byte[] machineSid = LookupSidBytes(Environment.MachineName);
            if (machineSid == null)
            {
                Console.Error.WriteLine(PROGRAM_NAME + ": ERROR: could not resolve the local machine SID");
                return 1;
            }

            List<string> names = EnumLocalUserNames();
            if (names == null)
            {
                Console.Error.WriteLine(PROGRAM_NAME + ": ERROR: NetUserEnum failed");
                return 1;
            }

            List<string> lines = new List<string>();
            for (int i = 0; i < names.Count; i++)
            {
                string loginName = names[i];

                // Guard kept from the PowerShell version: a name that starts with
                // a single quote is not a usable login name.
                if (loginName.Length == 0 || loginName[0] == '\'')
                    continue;

                USER_INFO_2 info;
                if (!TryGetUserInfo(loginName, out info))
                    continue;

                // Disabled accounts are never selectable in the wizard.
                if ((info.flags & UF_ACCOUNTDISABLE) != 0)
                    continue;

                byte[] sid;
                uint sidType;
                if (!TryLookupSid(loginName, out sid, out sidType))
                    continue;
                if (sidType != SidTypeUser || !SidBelongsToMachine(sid, machineSid))
                    continue;

                lines.Add(loginName + "|" + BuildDisplayLabel(loginName, info.full_name, sid));
            }

            File.WriteAllLines(outPath, lines.ToArray(), new UTF8Encoding(true));
            Console.WriteLine("LISTUSERS|RESULT=OK|COUNT=" + lines.Count);
            return 0;
        }

        // Level 0 is used for the enumeration itself because it is the only level
        // whose record shape is fixed by the ABI: one LPWSTR per entry, so the
        // stride is exactly one pointer. The level-2 record length differs between
        // Windows builds (152 bytes on Win11 x64 vs 160 in the SDK header), which
        // makes walking a level-2 *array* unsafe - it produced an access violation
        // the first time this was written. Details are therefore fetched per
        // account with NetUserGetInfo, which returns a single record and costs
        // microseconds.
        private static List<string> EnumLocalUserNames()
        {
            List<string> names = new List<string>();
            IntPtr bufPtr = IntPtr.Zero;
            uint resumeHandle = 0;
            int status = NERR_Success;

            try
            {
                do
                {
                    uint entriesRead;
                    uint totalEntries;
                    status = NetUserEnum(null, 0, FILTER_NORMAL_ACCOUNT, out bufPtr, 0xFFFFFFFF,
                        out entriesRead, out totalEntries, ref resumeHandle);

                    if (status != NERR_Success && status != ERROR_MORE_DATA)
                        break;

                    for (uint i = 0; i < entriesRead; i++)
                    {
                        IntPtr namePtr = Marshal.ReadIntPtr(bufPtr, (int)i * IntPtr.Size);
                        if (namePtr == IntPtr.Zero)
                            continue;
                        string name = Marshal.PtrToStringUni(namePtr);
                        if (!string.IsNullOrEmpty(name))
                            names.Add(name.Trim());
                    }

                    if (bufPtr != IntPtr.Zero)
                    {
                        NetApiBufferFree(bufPtr);
                        bufPtr = IntPtr.Zero;
                    }
                }
                while (status == ERROR_MORE_DATA);
            }
            finally
            {
                if (bufPtr != IntPtr.Zero)
                    NetApiBufferFree(bufPtr);
            }

            if (status != NERR_Success && status != ERROR_MORE_DATA)
                return null;

            return names;
        }

        // One USER_INFO_2 record (flags + full name) for a single account.
        private static bool TryGetUserInfo(string loginName, out USER_INFO_2 info)
        {
            info = new USER_INFO_2();
            IntPtr bufPtr = IntPtr.Zero;
            try
            {
                int status = NetUserGetInfo(null, loginName, 2, out bufPtr);
                if (status != NERR_Success || bufPtr == IntPtr.Zero)
                    return false;
                info = (USER_INFO_2)Marshal.PtrToStructure(bufPtr, typeof(USER_INFO_2));
                return true;
            }
            finally
            {
                if (bufPtr != IntPtr.Zero)
                    NetApiBufferFree(bufPtr);
            }
        }

        private static byte[] LookupSidBytes(string accountName)
        {
            byte[] sid;
            uint sidType;
            if (!TryLookupSid(accountName, out sid, out sidType))
                return null;
            return sid;
        }

        // Two-pass LookupAccountName: the first call only learns the buffer sizes.
        private static bool TryLookupSid(string accountName, out byte[] sid, out uint sidType)
        {
            sid = null;
            sidType = 0;
            uint cbSid = 0;
            uint cbDomain = 0;
            uint use;

            if (LookupAccountName(null, accountName, IntPtr.Zero, ref cbSid, null, ref cbDomain, out use))
                return false;   // should never succeed without a buffer
            if (Marshal.GetLastWin32Error() != ERROR_INSUFFICIENT_BUFFER || cbSid == 0)
                return false;

            IntPtr sidPtr = Marshal.AllocHGlobal((int)cbSid);
            try
            {
                uint cbSidLocal = cbSid;
                StringBuilder domain = new StringBuilder((int)cbDomain + 1);
                if (!LookupAccountName(null, accountName, sidPtr, ref cbSidLocal, domain, ref cbDomain, out use))
                    return false;

                byte[] copy = new byte[cbSidLocal];
                Marshal.Copy(sidPtr, copy, 0, (int)cbSidLocal);
                sid = copy;
                sidType = use;
                return true;
            }
            finally
            {
                Marshal.FreeHGlobal(sidPtr);
            }
        }

        // A local account SID is the machine SID plus one extra sub-authority (the
        // RID), so this is exactly "same SAM domain". The sub-authority COUNT byte
        // must be skipped when comparing (the machine SID has 4 of them, an account
        // SID has 5), which is why a naive byte-prefix test rejected every account.
        private static bool SidBelongsToMachine(byte[] sid, byte[] machineSid)
        {
            if (sid == null || machineSid == null)
                return false;
            if (sid.Length < 8 || machineSid.Length < 8)
                return false;

            int userSubCount = sid[1];
            int machineSubCount = machineSid[1];
            if (userSubCount != machineSubCount + 1)
                return false;
            if (sid.Length < 8 + userSubCount * 4 || machineSid.Length < 8 + machineSubCount * 4)
                return false;

            // Identifier authority (bytes 2..7): S-1-5-...
            for (int i = 2; i < 8; i++)
            {
                if (sid[i] != machineSid[i])
                    return false;
            }
            // Sub-authorities minus the trailing RID.
            for (int i = 0; i < machineSubCount * 4; i++)
            {
                if (sid[8 + i] != machineSid[8 + i])
                    return false;
            }
            return true;
        }

        private static string BuildDisplayLabel(string loginName, string fullName, byte[] sid)
        {
            string detail = (fullName == null) ? "" : fullName.Trim();
            if (detail.Length == 0)
                detail = ReadIdentityCacheUserName(sid);
            if (detail.Length == 0 || string.Equals(detail, loginName, StringComparison.OrdinalIgnoreCase))
                return loginName;
            return loginName + " (" + detail + ")";
        }

        // Microsoft-account (online) logins store their e-mail address here; the
        // old PowerShell query read the same per-user key.
        private static string ReadIdentityCacheUserName(byte[] sid)
        {
            try
            {
                if (sid == null)
                    return "";
                string sidString = new SecurityIdentifier(sid, 0).Value;
                if (string.IsNullOrEmpty(sidString))
                    return "";
                using (Microsoft.Win32.RegistryKey key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(
                    @"SOFTWARE\Microsoft\IdentityStore\Cache\" + sidString +
                    @"\IdentityCache\" + sidString))
                {
                    if (key == null)
                        return "";
                    object value = key.GetValue("UserName");
                    if (value == null)
                        return "";
                    string text = Convert.ToString(value);
                    return (text == null) ? "" : text.Trim();
                }
            }
            catch (Exception)
            {
                return "";
            }
        }

        // ---- Entry point -----------------------------------------------------

        // True when arg matches any of the supplied verb spellings.
        private static bool IsVerb(string arg, params string[] spellings)
        {
            for (int i = 0; i < spellings.Length; i++)
            {
                if (string.Equals(arg, spellings[i], StringComparison.OrdinalIgnoreCase))
                    return true;
            }
            return false;
        }

        // One usage screen for both callers: --help (stdout, exit 0) and a
        // missing/unknown argument (stderr, exit 99).
        private static void PrintUsage(TextWriter writer)
        {
            writer.WriteLine(PROGRAM_NAME + " " + PROGRAM_VERSION + " - RDPWrapKit installer sidecar");
            writer.WriteLine();
            writer.WriteLine("  " + PROGRAM_NAME + ".exe [--sign] <rdp-file>");
            writer.WriteLine("      Sign an .rdp file with the RDPWrapKit certificate.");
            writer.WriteLine("  " + PROGRAM_NAME + ".exe --verify <file> [expectedSubjectSubstring]");
            writer.WriteLine("      Authenticode publisher check (default CN=Microsoft Corporation).");
            writer.WriteLine("  " + PROGRAM_NAME + ".exe --list-users <out-file>");
            writer.WriteLine("      Enumerate enabled local accounts as: <login>|<display> per line.");
            writer.WriteLine("  " + PROGRAM_NAME + ".exe --protect <plain-file> <out-file>");
            writer.WriteLine("      DPAPI-protect a password for an .rdp file.");
            writer.WriteLine("      --encrypt-password is accepted as the legacy alias.");
            writer.WriteLine("  " + PROGRAM_NAME + ".exe --help");
            writer.WriteLine("      Show this screen.");
            writer.WriteLine();
            writer.WriteLine("Exit codes: 0 ok, 1 certificate/verify/resolve failure, 2 file missing,");
            writer.WriteLine("            3 bad RDP field, 4 signing failed, 5 exception, 99 bad arguments.");
        }

        private static int Main(string[] args)
        {
            Stopwatch sw = Stopwatch.StartNew();

            try
            {
                // Verb dispatch. Every verb is explicit except for the bare-path
                // form, which stays the default signing behaviour so existing
                // installer callers keep working unchanged.
                if (args.Length >= 1 && IsVerb(args[0], "--help", "-h", "-?", "/?"))
                {
                    PrintUsage(Console.Out);
                    return 0;
                }

                if (args.Length >= 1 && IsVerb(args[0], "--protect", "--encrypt-password"))
                {
                    string plainPath = args.Length >= 2 ? args[1].Trim('"') : "";
                    string encPath = args.Length >= 3 ? args[2].Trim('"') : "";
                    return RunProtectSecret(plainPath, encPath);
                }

                if (args.Length >= 1 && string.Equals(args[0], "--verify", StringComparison.OrdinalIgnoreCase))
                {
                    string verifyPath = args.Length >= 2 ? args[1].Trim('"') : "";
                    string expectedPublisher = args.Length >= 3 ? args[2].Trim('"') : "CN=Microsoft Corporation";
                    return RunVerify(verifyPath, expectedPublisher);
                }

                if (args.Length >= 1 && string.Equals(args[0], "--list-users", StringComparison.OrdinalIgnoreCase))
                {
                    string usersOutPath = args.Length >= 2 ? args[1].Trim('"') : "";
                    return RunListUsers(usersOutPath);
                }

                // Anything else starting with "--" is an unknown verb, not a file
                // path. Without this check a typo fell through to the signing path
                // and reported the misleading "File not found: --nope".
                if (args.Length >= 1 && args[0].StartsWith("--", StringComparison.Ordinal))
                {
                    Console.Error.WriteLine(PROGRAM_NAME + ": ERROR: unknown option: " + args[0]);
                    PrintUsage(Console.Error);
                    return 99;
                }

                // "--sign <file>" is the explicit spelling of the bare-path default.
                int pathArg = 0;
                if (args.Length >= 1 && string.Equals(args[0], "--sign", StringComparison.OrdinalIgnoreCase))
                    pathArg = 1;

                if (args.Length <= pathArg || string.IsNullOrWhiteSpace(args[pathArg]))
                {
                    Console.Error.WriteLine(PROGRAM_NAME + ": ERROR: missing or unknown arguments");
                    PrintUsage(Console.Error);
                    return 99;
                }

                string rdpPath = args[pathArg].Trim('"');
                Verbose(PROGRAM_NAME + " " + PROGRAM_VERSION + " starting");

                // ---- Step 1: Validate RDP file exists -------------------------
                Verbose("RdpPath = " + rdpPath);
                if (!File.Exists(rdpPath))
                {
                    Console.Error.WriteLine(PROGRAM_NAME + ": ERROR: File not found: " + rdpPath);
                    return 2;
                }

                // ---- Step 2: Find the signing cert ----------------------------
                Verbose("Looking for signing certificate...");
                X509Certificate2 cert = FindSigningCert();
                if (cert == null)
                {
                    Console.Error.WriteLine(PROGRAM_NAME + ": ERROR: Signing certificate not found. Run EnsureRDPSigningCert first.");
                    return 1;
                }
                string thumb8 = (cert.Thumbprint != null && cert.Thumbprint.Length >= 8)
                    ? cert.Thumbprint.Substring(0, 8) : "????";
                Verbose("Certificate found: " + cert.Subject + " (thumb=" + thumb8 + "...)");

                // ---- Step 3: Read and parse RDP file --------------------------
                Verbose("Reading RDP file...");
                byte[] inputBytes = File.ReadAllBytes(rdpPath);
                string rawText;

                // Detect UTF-16LE BOM
                if (inputBytes.Length >= 2 && inputBytes[0] == 0xFF && inputBytes[1] == 0xFE)
                {
                    rawText = Encoding.Unicode.GetString(inputBytes, 2, inputBytes.Length - 2);
                    Verbose("Detected UTF-16LE encoding (BOM present)");
                }
                else
                {
                    rawText = Encoding.UTF8.GetString(inputBytes);
                    Verbose("Detected UTF-8 encoding (no BOM)");
                }

                // Split into lines (handle \r\r\n, \r\n, \r, \n)
                string[] inputLines = rawText.Split(
                    new[] { "\r\r\n", "\r\n", "\r", "\n" },
                    StringSplitOptions.RemoveEmptyEntries);
                Verbose("Parsed " + inputLines.Length + " lines");

                // ---- Step 4: Build field map ----------------------------------
                var fieldMap = new Dictionary<string, FieldEntry>(StringComparer.OrdinalIgnoreCase);
                foreach (string line in inputLines)
                {
                    Match match = Regex.Match(line, @"^(.+?):(.):(.*?)$");
                    if (match.Success)
                    {
                        string key = match.Groups[1].Value.Trim().ToLowerInvariant();
                        FieldEntry entry;
                        entry.Name = match.Groups[1].Value.Trim();
                        entry.Type = match.Groups[2].Value[0];
                        entry.Value = match.Groups[3].Value;
                        fieldMap[key] = entry;
                    }
                }

                if (!fieldMap.ContainsKey("full address"))
                {
                    Console.Error.WriteLine(PROGRAM_NAME + ": ERROR: Missing required 'full address' field in RDP file.");
                    return 3;
                }
                Verbose("Field map built with " + fieldMap.Count + " entries");

                // ---- Step 5: Build base lines (strip old signscope/signature) --
                var baseLines = new List<string>();
                foreach (string line in inputLines)
                {
                    string lineTrimmed = line.Trim();
                    if (string.IsNullOrEmpty(lineTrimmed))
                        continue;

                    Match binaryMatch = Regex.Match(lineTrimmed, @"^(.+?):b:(.*)$");
                    if (binaryMatch.Success)
                    {
                        string key = binaryMatch.Groups[1].Value.Trim().ToLowerInvariant();
                        if (!StripKeys.Contains(key))
                            baseLines.Add(binaryMatch.Groups[1].Value.Trim() + ":b:" + binaryMatch.Groups[2].Value.Trim().ToUpperInvariant());
                        // Binary fields (password 51:b) are NEVER in signscope
                    }
                    else
                    {
                        Match fieldMatch = Regex.Match(lineTrimmed, @"^(.+?):");
                        if (fieldMatch.Success)
                        {
                            string key = fieldMatch.Groups[1].Value.Trim().ToLowerInvariant();
                            if (!StripKeys.Contains(key))
                                baseLines.Add(lineTrimmed);
                        }
                        else
                        {
                            // Skip orphaned lines that look like bare base64 data
                            // (e.g. old signature continuation without 'signature:s:' prefix).
                            // These are artifacts from previous signings that used a different
                            // wrapping format.  Valid RDP fields always have a colon.
                            if (lineTrimmed.IndexOf(':') < 0)
                            {
                                // Pure base64 chars: A-Za-z0-9+/=
                                bool looksLikeBase64 = true;
                                for (int ci = 0; ci < lineTrimmed.Length; ci++)
                                {
                                    char c = lineTrimmed[ci];
                                    if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                                          (c >= '0' && c <= '9') || c == '+' || c == '/' || c == '='))
                                    {
                                        looksLikeBase64 = false;
                                        break;
                                    }
                                }
                                if (!looksLikeBase64)
                                    baseLines.Add(lineTrimmed);
                                // else: skip — it's orphaned base64 signature data
                            }
                            else
                            {
                                baseLines.Add(lineTrimmed);
                            }
                        }
                    }
                }
                Verbose("Built " + baseLines.Count + " base lines (stripped old signature)");

                // ---- Step 6: Build canonical signscope ------------------------
                string altFullAddress = fieldMap["full address"].Value;

                // Override alternate full address in the field map so the canonical
                // signscope always includes the correct value, even when the input
                // file is missing this field (e.g. newly-created shortcuts that
                // have never been signed before).  This matches the legacy PS
                // implementation and avoids a mismatch where the output file
                // receives alternate full address = fullAddress but the signature
                // was computed with alternate full address = "".
                FieldEntry altEntry;
                altEntry.Name = "alternate full address";
                altEntry.Type = 's';
                altEntry.Value = altFullAddress;
                fieldMap["alternate full address"] = altEntry;

                // Build signscope from Microsoft's canonical field list.
                // Only include fields that actually exist in the file body.
                // This matches rdpsign.exe behavior exactly — same fields, same canonical order.
                var effectiveScopeFields = new List<string>();
                foreach (CanonicalFieldInfo cfi in CANONICAL_SIGNSCOPE)
                {
                    if (fieldMap.ContainsKey(cfi.Key))
                        effectiveScopeFields.Add(cfi.DisplayName);
                }
                string effectiveSignscope = string.Join(",", effectiveScopeFields);

                string[] scopeFields = effectiveSignscope.Split(',');

                StringBuilder sb = new StringBuilder();
                foreach (string sf in scopeFields)
                {
                    string key = sf.Trim().ToLowerInvariant();
                    string typ;
                    string val;

                    FieldEntry entry;
                    char mappedType;
                    if (fieldMap.TryGetValue(key, out entry))
                    {
                        typ = entry.Type.ToString();
                        val = entry.Value;
                    }
                    else if (FieldTypeMap.TryGetValue(key, out mappedType))
                    {
                        typ = mappedType.ToString();
                        val = (mappedType == 's') ? "" : "0";
                    }
                    else
                    {
                        // Unknown field - skip
                        continue;
                    }

                    sb.Append(key + ":" + typ + ":" + val + "\r\n");
                }
                sb.Append("signscope:s:" + effectiveSignscope + "\r\n");
                sb.Append('\0'); // null terminator

                byte[] canonicalBytes = Encoding.Unicode.GetBytes(sb.ToString());
                Verbose("Canonical signscope built (" + canonicalBytes.Length + " bytes)");

                // ---- Step 7: Sign via CryptSignMessage ------------------------
                Verbose("Calling CryptSignMessage...");
                byte[] cmsBytes = SignDetached(canonicalBytes, cert);
                Verbose("CMS signature produced (" + cmsBytes.Length + " bytes)");

                // ---- Step 8: Build output RDP content -------------------------
                byte[] header = { 0x01, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00 };
                byte[] sigBlob = Combine(header, BitConverter.GetBytes((uint)cmsBytes.Length), cmsBytes);
                string b64Raw = Convert.ToBase64String(sigBlob);

                // Wrap base64: insert two spaces after every 64 characters, keeping
                // the ENTIRE signature value on ONE RDP file line (matching rdpsign.exe
                // and the original PowerShell implementation exactly).
                // Regex equivalent: .Replace(b64Raw, '.{1,64}', '$0  ')
                StringBuilder b64Wrapped = new StringBuilder(b64Raw.Length + (b64Raw.Length / 64 + 1) * 2);
                for (int i = 0; i < b64Raw.Length; i += 64)
                {
                    int len = Math.Min(64, b64Raw.Length - i);
                    b64Wrapped.Append(b64Raw, i, len);
                    b64Wrapped.Append("  "); // two-space separator — stays on same line
                }
                string sigB64 = b64Wrapped.ToString().TrimEnd(' ');

                // Build output lines
                var outLines = new List<string>(baseLines);
                outLines.Add("alternate full address:s:" + altFullAddress);
                outLines.Add("signscope:s:" + effectiveSignscope);
                outLines.Add("signature:s:" + sigB64);

                string outText = string.Join("\r\n", outLines) + "\r\n";
                byte[] outBytes = Combine(
                    new byte[] { 0xFF, 0xFE },  // UTF-16LE BOM
                    Encoding.Unicode.GetBytes(outText));

                // ---- Step 9: Write signed RDP file ---------------------------
                Verbose("Writing signed RDP file (" + outBytes.Length + " bytes)...");
                File.WriteAllBytes(rdpPath, outBytes);

                Verbose(PROGRAM_NAME + " completed successfully in " + sw.ElapsedMilliseconds + "ms");
                return 0;
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine(PROGRAM_NAME + ": ERROR: " + ex.GetType().Name + ": " + ex.Message);
                if (ex.InnerException != null)
                    Console.Error.WriteLine(PROGRAM_NAME + ": INNER: " + ex.InnerException.Message);
                Console.Error.WriteLine(PROGRAM_NAME + ": STACK: " + ex.StackTrace);
                return 5;
            }
        }

        // ---- Helpers ---------------------------------------------------------

        private static X509Certificate2 FindSigningCert()
        {
            X509Store store = new X509Store(StoreName.My, StoreLocation.LocalMachine);
            try
            {
                store.Open(OpenFlags.OpenExistingOnly | OpenFlags.ReadOnly);
                foreach (X509Certificate2 cert in store.Certificates)
                {
                    if (string.Equals(cert.Subject, CERT_SUBJECT, StringComparison.OrdinalIgnoreCase))
                        return cert;
                }
            }
            finally
            {
                store.Close();
            }
            return null;
        }

        private static byte[] SignDetached(byte[] content, X509Certificate2 cert)
        {
            if (content == null) throw new ArgumentNullException("content");
            if (cert == null) throw new ArgumentNullException("cert");
            if (content.Length == 0) throw new ArgumentException("Content must not be empty.", "content");

            IntPtr certPtrArr = Marshal.AllocHGlobal(IntPtr.Size);
            try
            {
                Marshal.WriteIntPtr(certPtrArr, cert.Handle);

                CRYPT_SIGN_MESSAGE_PARA para = new CRYPT_SIGN_MESSAGE_PARA();
                para.cbSize = (uint)Marshal.SizeOf(typeof(CRYPT_SIGN_MESSAGE_PARA));
                para.dwMsgEncodingType = MSG_ENCODING;
                para.pSigningCert = cert.Handle;
                para.HashAlgorithm = new CRYPT_ALGORITHM_IDENTIFIER();
                para.HashAlgorithm.pszObjId = "2.16.840.1.101.3.4.2.1"; // SHA-256
                para.cMsgCert = 1u;
                para.rgpMsgCert = certPtrArr;

                GCHandle handle = GCHandle.Alloc(content, GCHandleType.Pinned);
                try
                {
                    IntPtr contentPtr = handle.AddrOfPinnedObject();
                    IntPtr[] rgpb = { contentPtr };
                    uint[] rgcb = { (uint)content.Length };

                    // Query size
                    uint cbBlob = 0;
                    if (!CryptSignMessage(ref para, true, 1u, rgpb, rgcb, null, ref cbBlob))
                    {
                        int err = Marshal.GetLastWin32Error();
                        throw new Win32Exception(err, "CryptSignMessage size query failed (error " + err + ")");
                    }

                    if (cbBlob == 0)
                        throw new Win32Exception(0, "CryptSignMessage returned zero-size output buffer.");

                    // Produce signature
                    byte[] blob = new byte[cbBlob];
                    if (!CryptSignMessage(ref para, true, 1u, rgpb, rgcb, blob, ref cbBlob))
                    {
                        int err = Marshal.GetLastWin32Error();
                        throw new Win32Exception(err, "CryptSignMessage failed (error " + err + ")");
                    }

                    if (cbBlob == blob.Length)
                        return blob;

                    byte[] trimmed = new byte[cbBlob];
                    Buffer.BlockCopy(blob, 0, trimmed, 0, (int)cbBlob);
                    return trimmed;
                }
                finally
                {
                    if (handle.IsAllocated)
                        handle.Free();
                }
            }
            finally
            {
                Marshal.FreeHGlobal(certPtrArr);
            }
        }

        private static byte[] Combine(params byte[][] arrays)
        {
            int total = 0;
            for (int i = 0; i < arrays.Length; i++)
                total += arrays[i].Length;

            byte[] result = new byte[total];
            int offset = 0;
            for (int i = 0; i < arrays.Length; i++)
            {
                Buffer.BlockCopy(arrays[i], 0, result, offset, arrays[i].Length);
                offset += arrays[i].Length;
            }
            return result;
        }

        [Conditional("DEBUG")]
        private static void Verbose(string message)
        {
            // Writes to stderr so they don't interfere with stdout (not used here)
            Console.Error.WriteLine(PROGRAM_NAME + ": " + message);
        }

        private struct FieldEntry
        {
            public string Name;
            public char Type;
            public string Value;
        }

        private struct CanonicalFieldInfo
        {
            public string Key;
            public string DisplayName;
            public CanonicalFieldInfo(string key, string displayName)
            {
                Key = key;
                DisplayName = displayName;
            }
        }
    }
}
